package panel

import (
	"encoding/json"
	"fmt"
	"net/http"
	"reflect"
	"sort"
	"strings"

	"github.com/gin-gonic/gin"
	"github.com/hann0w0/singbox-panel/internal/domain/model"
	"github.com/hann0w0/singbox-panel/internal/domain/singbox"
)

type nodeJSONRequest struct {
	Kind      string          `json:"kind"`
	Direction string          `json:"direction"`
	ID        uint            `json:"id"`
	Body      json.RawMessage `json:"body"`
	Config    json.RawMessage `json:"config"`
}

// Every explicitly supplied JSON value must survive conversion. Extra fields
// generated by the panel are defaults; lost or changed input is an error, not
// a best-effort import. Paths, never credential values, are returned to the UI.
func changedJSONPath(input, output any, path string) string {
	switch in := input.(type) {
	case map[string]any:
		out, ok := output.(map[string]any)
		if !ok {
			return path
		}
		keys := make([]string, 0, len(in))
		for key := range in {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		for _, key := range keys {
			next := path + "." + key
			value, exists := out[key]
			if !exists {
				return next
			}
			if changed := changedJSONPath(in[key], value, next); changed != "" {
				return changed
			}
		}
	case []any:
		out, ok := output.([]any)
		if !ok || len(in) != len(out) {
			return path
		}
		for i := range in {
			if changed := changedJSONPath(in[i], out[i], fmt.Sprintf("%s[%d]", path, i)); changed != "" {
				return changed
			}
		}
	default:
		if !reflect.DeepEqual(input, output) {
			return path
		}
	}
	return ""
}

func checkNodeJSONLoss(input json.RawMessage, output json.RawMessage) error {
	var before, after any
	if err := json.Unmarshal(input, &before); err != nil {
		return err
	}
	if err := json.Unmarshal(output, &after); err != nil {
		return err
	}
	if path := changedJSONPath(before, after, "$"); path != "" {
		return fmt.Errorf("字段 %s 无法由面板完整保留，请调整该字段；完整自定义配置可使用服务器的原始配置模式", path)
	}
	return nil
}

func renderOutboundJSON(body outboundReq) (json.RawMessage, error) {
	var st outboundStoredSettings
	if err := json.Unmarshal(body.Settings, &st); err != nil {
		return nil, err
	}
	raw, err := singbox.BuildServerConfig(singbox.ServerConfigInput{Outbounds: []singbox.OutboundInput{{
		Tag: body.Tag, Type: body.Type, Server: st.Server, ServerPort: st.ServerPort,
		Username: st.Username, UUID: st.UUID, Password: st.Password, Settings: st.Settings,
	}}})
	if err != nil {
		return nil, err
	}
	var config struct {
		Outbounds []json.RawMessage `json:"outbounds"`
	}
	if err := json.Unmarshal(raw, &config); err != nil {
		return nil, err
	}
	for _, item := range config.Outbounds {
		var ob struct {
			Tag  string `json:"tag"`
			Type string `json:"type"`
		}
		if err := json.Unmarshal(item, &ob); err != nil {
			return nil, err
		}
		if ob.Tag == body.Tag && ob.Type == body.Type {
			return item, nil
		}
	}
	return nil, fmt.Errorf("无法生成出站 JSON")
}

func renderInboundJSON(body inboundReq, st singbox.InboundSettings) (json.RawMessage, error) {
	raw, err := singbox.BuildInbound(singbox.InboundInput{Tag: body.Tag, Type: body.Type, ListenPort: body.ListenPort, Settings: st})
	if err != nil {
		return nil, err
	}
	if st.UseMultiUser(body.Type) {
		// Users are reconciled from panel grants when the real config is built.
		// Never expose a lockout credential or allow this editor to replace grants.
		var object map[string]json.RawMessage
		if err := json.Unmarshal(raw, &object); err != nil {
			return nil, err
		}
		delete(object, "users")
		return json.Marshal(object)
	}
	return raw, nil
}

func (a *App) convertNodeJSON(c *gin.Context) {
	sid, ok := uintParam(c, "id")
	if !ok || !a.requireManagedMode(c, sid) {
		return
	}
	c.Header("Cache-Control", "no-store")
	var req nodeJSONRequest
	if !bindJSON(c, &req) {
		return
	}
	if (req.Kind != "inbound" && req.Kind != "outbound") || (req.Direction != "encode" && req.Direction != "decode") {
		c.JSON(http.StatusBadRequest, gin.H{"error": "无效的 JSON 转换类型"})
		return
	}
	var object map[string]any
	var parsed *singbox.ParsedConfig
	if req.Direction == "decode" {
		if len(req.Config) > 512*1024 || json.Unmarshal(req.Config, &object) != nil || object == nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "请输入单个入站或出站 JSON 对象（最多 512 KB）"})
			return
		}
		wrapped, err := json.Marshal(map[string]any{req.Kind + "s": []json.RawMessage{req.Config}})
		if err == nil {
			parsed, err = singbox.ParseServerConfig(wrapped)
		}
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
	}
	var body any
	var config json.RawMessage
	var err error
	managedUsers := false
	if req.Kind == "inbound" {
		var in inboundReq
		if err = json.Unmarshal(req.Body, &in); err == nil {
			var originalType string
			if req.ID != 0 {
				var row model.Inbound
				if e := a.db.Where("id = ? AND server_id = ?", req.ID, sid).First(&row).Error; e != nil {
					c.JSON(http.StatusNotFound, gin.H{"error": "入站不存在"})
					return
				}
				originalType = string(row.Type)
			}
			var st singbox.InboundSettings
			if len(in.Settings) > 0 {
				err = json.Unmarshal(in.Settings, &st)
			}
			if err == nil && req.Direction == "decode" {
				if len(parsed.Inbounds) != 1 {
					err = fmt.Errorf("不支持的入站协议或 JSON 结构")
				} else {
					item := parsed.Inbounds[0]
					previous := st
					managedUsers = in.Type == item.Type && previous.UseMultiUser(item.Type)
					if _, supplied := object["users"]; managedUsers && supplied {
						err = fmt.Errorf("此入站的用户由面板统一管理，请移除 users 字段；用户凭据会在下发时自动填入")
					} else if item.UserCount > 1 {
						err = fmt.Errorf("多个用户请通过表单的多用户模式及用户授权管理，JSON 模式仅支持固定凭据")
					}
					st = item.Settings
					if in.Type == item.Type {
						st.VMessSecurity = previous.VMessSecurity
						st.PacketEncoding = previous.PacketEncoding
						st.AnyTLSUDPOverStream = previous.AnyTLSUDPOverStream
						st.TLS.Fingerprint = previous.TLS.Fingerprint
						st.TLS.Insecure = previous.TLS.Insecure
						if st.TLS.Certificate == previous.TLS.Certificate && st.TLS.Key == previous.TLS.Key {
							st.TLS.SelfSigned = previous.TLS.SelfSigned
						}
					}
					st.MultiUser, st.SingleUser = managedUsers, !managedUsers
					in.Type, in.Tag, in.ListenPort = item.Type, item.Tag, item.ListenPort
				}
			}
			if err == nil && (!supportedInboundTypes[in.Type] || (originalType != "" && originalType != in.Type)) {
				err = fmt.Errorf("不支持该入站协议，已有入站不能更改协议类型")
			}
			if err == nil {
				err = fillInboundSecrets(in.Type, &st)
			}
			if err == nil {
				in.Tag = inboundTag(in.Type, in.Tag)
				managedUsers = st.UseMultiUser(in.Type)
				in.Settings, err = json.Marshal(st)
			}
			if err == nil {
				config, err = renderInboundJSON(in, st)
			}
			if err == nil && req.Direction == "decode" {
				err = a.validateInboundIdentity(a.db, sid, req.ID, in.Tag, in.ListenPort)
			}
			body = in
		}
	} else {
		var out outboundReq
		err = json.Unmarshal(req.Body, &out)
		if err == nil && req.ID != 0 {
			var row model.Outbound
			if e := a.db.Where("id = ? AND server_id = ?", req.ID, sid).First(&row).Error; e != nil {
				c.JSON(http.StatusNotFound, gin.H{"error": "出站不存在"})
				return
			}
		}
		if err == nil && req.Direction == "decode" {
			if len(parsed.Outbounds) != 1 {
				err = fmt.Errorf("不支持的出站协议、内置标签或 JSON 结构")
			} else {
				item := parsed.Outbounds[0]
				if item.Type == "vless" {
					item.Settings.PacketEncoding, _ = object["packet_encoding"].(string)
				}
				out.Tag, out.Type = item.Tag, item.Type
				out.Settings, err = json.Marshal(outboundStoredSettings{Server: item.Server, ServerPort: item.ServerPort,
					UUID: item.UUID, Username: item.Username, Password: item.Password, Settings: item.Settings})
			}
		}
		if err == nil && (!supportedOutboundTypes[out.Type] || out.Type == "direct") {
			err = fmt.Errorf("不支持该出站协议")
		}
		if err == nil && req.Direction == "encode" && strings.TrimSpace(out.Tag) == "" {
			out.Tag, err = a.availableOutboundTag(sid, "proxy")
		}
		if err == nil {
			config, err = renderOutboundJSON(out)
		}
		if err == nil && req.Direction == "decode" {
			err = a.validateOutbound(a.db, sid, req.ID, out.Tag, out.Type, out.Settings)
		}
		body = out
	}
	if err == nil && req.Direction == "decode" {
		err = checkNodeJSONLoss(req.Config, config)
	}
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}
	c.JSON(http.StatusOK, gin.H{"body": body, "config": config, "managed_users": managedUsers})
}
